{
    if (A.rankType == GPU)
    {
#ifdef USE_CUDA
        SetupHalo_Gpu(A);
#endif
    }
    else
    {
#ifdef USE_AARCH64
        SetupHalo_Cpu(A);
#endif
    }
}

