#include "hpcg.hpp"

#include "ComputeDotProduct.hpp"
#include "ComputeMG.hpp"
#include "ComputeResidual.hpp"
#include "ComputeSPMV.hpp"
#include "CpuKernels.hpp"
#include "CudaKernels.hpp"
#include "Geometry.hpp"
